// Compare page (dual build): reads trainings' checkpoint folders and drives the user's ComfyUI.
// Every sample is generated by Comfy from one of the user's API-format workflows; AITK only
// patches the LoRA, prompt, sampler settings, size and model/TE/VAE into a copy per image.
import fs from 'fs';
import path from 'path';
import YAML from 'yaml';
import prisma from '@/server/prisma';
import { getTrainingFolder } from '@/server/settings';
import type { CompareRun, CompareSettings, ScannedFile, ScannedRun } from '@/utils/compare';

type RunCfg = Record<string, string | number | null>;

// ---------- trainings / checkpoints ----------

// safetensors header: 8-byte little-endian length, then that many bytes of JSON
export async function readSafetensorsMeta(file: string): Promise<Record<string, string> | null> {
  let fd: fs.promises.FileHandle | null = null;
  try {
    fd = await fs.promises.open(file, 'r');
    const lenBuf = Buffer.alloc(8);
    await fd.read(lenBuf, 0, 8, 0);
    const n = Number(lenBuf.readBigUInt64LE(0));
    if (!n || n > 100 * 1024 * 1024) return null;
    const head = Buffer.alloc(n);
    await fd.read(head, 0, n, 8);
    return JSON.parse(head.toString('utf8')).__metadata__ ?? null;
  } catch {
    return null;
  } finally {
    await fd?.close();
  }
}

const stepFromMeta = (meta: Record<string, string> | null): number | null => {
  try {
    const step = JSON.parse(meta?.training_info ?? '{}').step;
    return typeof step === 'number' ? step : null;
  } catch {
    return null;
  }
};

// trailing number in the name: _000003000 (AITK) or _3000 (renamed copies)
const stepFromName = (file: string): number | null => {
  const m = path.parse(file).name.match(/_(\d+)$/);
  return m ? parseInt(m[1], 10) : null;
};

export async function scanFolder(folder: string): Promise<{ files: ScannedFile[]; outputName: string | null }> {
  const names = (await fs.promises.readdir(folder)).filter(f => f.toLowerCase().endsWith('.safetensors'));
  let outputName: string | null = null;
  const files: ScannedFile[] = [];
  for (const file of names) {
    const full = path.join(folder, file);
    const meta = await readSafetensorsMeta(full);
    if (!outputName && meta?.ss_output_name) outputName = meta.ss_output_name;
    files.push({ path: full, file, step: stepFromMeta(meta) ?? stepFromName(file) });
  }
  files.sort((a, b) => (a.step ?? Infinity) - (b.step ?? Infinity) || a.file.localeCompare(b.file));
  // the final save and its _<step> copy can both exist; keep one file per step
  const seen = new Set<number>();
  return {
    files: files.filter(f => f.step === null || (!seen.has(f.step) && seen.add(f.step))),
    outputName,
  };
}

const baseName = (p: string) => (p || '').replace(/[\\/]+$/, '').split(/[\\/]/).pop() || '';

// LR as a plain decimal (0.0001, never 1e-4)
const fmtLr = (lr: any) => {
  const n = Number(lr);
  if (!isFinite(n)) return lr ?? null;
  return n.toFixed(12).replace(/\.?0+$/, '');
};

// the settings shown (when they differ) in the Compare column headers
export function cfgFromJobConfig(jobConfig: any): RunCfg {
  const p = jobConfig?.config?.process?.[0] ?? {};
  const ds: any[] = p.datasets ?? [];
  const res = Array.from(new Set(ds.flatMap(d => d.resolution ?? []))).sort((a: any, b: any) => a - b);
  return {
    model: baseName(p.model?.name_or_path ?? '') || null,
    quant: p.model?.quantize ? (p.model?.qtype ?? 'qfloat8') : 'none',
    type: p.network?.type ?? null,
    linear: p.network?.linear ?? null,
    linear_alpha: p.network?.linear_alpha ?? null,
    lokr_factor: p.network?.lokr_factor ?? null,
    dtype: p.train?.dtype ?? null,
    res: res.length ? res.join(', ') : null,
    dataset: ds.map(d => baseName(d.folder_path)).join(', ') || null,
    optimizer: p.train?.optimizer ?? null,
    timestep_type: p.train?.timestep_type ?? null,
    style: p.train?.content_or_style ?? null,
    lr: fmtLr(p.train?.lr),
    total: p.train?.steps ?? null,
  };
}

const hasLoras = (dir: string) =>
  fs.promises
    .readdir(dir)
    .then(f => f.some(n => n.toLowerCase().endsWith('.safetensors')))
    .catch(() => false);

// The job's own output folder, or, when its LoRAs were moved one level down (e.g.
// <training folder>\aitk_outputs\<job name>), that copy.
export async function jobFolder(job: { name: string; job_config: string }): Promise<string> {
  let trainingFolder = '';
  try {
    trainingFolder = JSON.parse(job.job_config)?.config?.process?.[0]?.training_folder ?? '';
  } catch {}
  const roots = Array.from(new Set([trainingFolder, await getTrainingFolder()].filter(Boolean)));
  const own = path.join(roots[0], job.name);
  if (await hasLoras(own)) return own;
  for (const root of roots) {
    for (const sub of await subfolders(root)) {
      const candidate = path.join(root, sub, job.name);
      if (await hasLoras(candidate)) return candidate;
    }
  }
  return own;
}

// listing the trainings checks every job, so read each training root's subfolders once per 30s
const subfolderCache = new Map<string, { at: number; dirs: string[] }>();
async function subfolders(root: string): Promise<string[]> {
  const hit = subfolderCache.get(root);
  if (hit && Date.now() - hit.at < 30000) return hit.dirs;
  const dirs = (await fs.promises.readdir(root, { withFileTypes: true }).catch(() => []))
    .filter(d => d.isDirectory())
    .map(d => d.name);
  subfolderCache.set(root, { at: Date.now(), dirs });
  return dirs;
}

export async function scanRun(run: CompareRun): Promise<ScannedRun> {
  const out: ScannedRun = { name: run.name, folder: '', files: [], cfg: null, cfgSource: 'none' };
  try {
    if (run.kind === 'job') {
      const job = await prisma.job.findUnique({ where: { id: run.jobId } });
      if (!job) throw new Error('Training no longer exists in AITK');
      out.name = job.name;
      out.folder = await jobFolder(job);
      out.cfg = cfgFromJobConfig(JSON.parse(job.job_config));
      out.cfgSource = 'job';
      out.files = (await scanFolder(out.folder)).files;
      return out;
    }
    out.folder = run.folder;
    const { files, outputName } = await scanFolder(run.folder);
    out.files = files;
    // renamed/audited copies still carry the original job name inside the files
    const job = outputName ? await prisma.job.findUnique({ where: { name: outputName } }) : null;
    if (job) {
      out.cfg = cfgFromJobConfig(JSON.parse(job.job_config));
      out.cfgSource = 'job';
    } else {
      const yamlPath = path.join(run.folder, 'config.yaml');
      if (fs.existsSync(yamlPath)) {
        out.cfg = cfgFromJobConfig(YAML.parse(await fs.promises.readFile(yamlPath, 'utf8')));
        out.cfgSource = 'config.yaml';
      }
    }
  } catch (e: any) {
    out.error = e?.message ?? String(e);
  }
  return out;
}

export const getCompareDefaults = async () => {
  const row = await prisma.settings.findFirst({ where: { key: 'COMPARE_DEFAULTS' } });
  try {
    return row?.value ? JSON.parse(row.value) : null;
  } catch {
    return null;
  }
};

// ---------- ComfyUI ----------

export const DEFAULT_COMFY_URL = 'http://127.0.0.1:8188';

export async function getComfyUrl(): Promise<string> {
  const row = await prisma.settings.findFirst({ where: { key: 'COMFY_URL' } });
  return (row?.value?.trim() || DEFAULT_COMFY_URL).replace(/\/+$/, '');
}

export async function comfyFetch(pathname: string, init: RequestInit & { timeoutMs?: number } = {}) {
  const { timeoutMs = 15000, ...rest } = init;
  return fetch((await getComfyUrl()) + pathname, { ...rest, signal: AbortSignal.timeout(timeoutMs), cache: 'no-store' });
}

export async function comfyJson(pathname: string, init: RequestInit & { timeoutMs?: number } = {}) {
  const res = await comfyFetch(pathname, init);
  if (!res.ok) throw new Error(`ComfyUI ${pathname} → HTTP ${res.status}: ${(await res.text()).slice(0, 500)}`);
  return res.json();
}

const objectInfoCache = new Map<string, { at: number; info: any }>();
export async function objectInfo(classType: string): Promise<any> {
  const hit = objectInfoCache.get(classType);
  if (hit && Date.now() - hit.at < 60000) return hit.info;
  const json = await comfyJson(`/api/object_info/${encodeURIComponent(classType)}`);
  const info = json?.[classType] ?? null;
  objectInfoCache.set(classType, { at: Date.now(), info });
  return info;
}

export async function listWorkflows(): Promise<string[]> {
  const list: string[] = await comfyJson('/api/userdata?dir=workflows&recurse=true');
  return list.filter(f => f.toLowerCase().endsWith('.json')).sort((a, b) => {
    // API exports first: they are the only ones Compare can send
    const api = (s: string) => (/\bapi\b/i.test(s) ? 0 : 1);
    return api(a) - api(b) || a.localeCompare(b);
  });
}

export async function loadWorkflow(name: string): Promise<ApiPrompt> {
  const json = await comfyJson(`/api/userdata/${encodeURIComponent('workflows/' + name)}`);
  if (!isApiWorkflow(json)) {
    throw new Error(
      `"${name}" is a regular workflow save. Compare needs the API format: in ComfyUI use File → Export (API).`,
    );
  }
  return json;
}

// ---------- workflow analysis + patching ----------

type ApiNode = { class_type: string; inputs: Record<string, any>; _meta?: { title?: string } };
export type ApiPrompt = Record<string, ApiNode>;

const isLink = (v: any): v is [string, number] =>
  Array.isArray(v) && v.length === 2 && typeof v[0] === 'string' && typeof v[1] === 'number';

export function isApiWorkflow(obj: any): obj is ApiPrompt {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj) || Array.isArray(obj.nodes)) return false;
  const nodes = Object.values(obj);
  return nodes.length > 0 && nodes.every((n: any) => n && typeof n.class_type === 'string' && typeof n.inputs === 'object');
}

const LM_LORA = 'Lora Loader (LoraManager)';
const LORA_CLASSES = [LM_LORA, 'LoraLoaderModelOnly', 'LoraLoader'];
const SAMPLER_RE = /KSampler|SamplerCustom/i;
// nodes in the sampler's chain whose seed/steps/cfg/sampler/scheduler widgets Compare overrides
const SAMPLER_CHAIN_RE = /KSampler|SamplerCustom|RandomNoise|Scheduler|SamplerSelect|Guider/i;
const SAMPLE_FIELDS: Record<string, string[]> = {
  seed: ['seed', 'noise_seed'],
  steps: ['steps'],
  cfg: ['cfg'],
  sampler: ['sampler_name'],
  scheduler: ['scheduler'],
};
const LOADER_FIELDS: Record<'model' | 'te' | 'vae', string[]> = {
  model: ['diffusion_model_name', 'unet_name', 'ckpt_name'],
  te: ['clip_name', 'clip_name1'],
  vae: ['vae_name'],
};

export interface WorkflowMap {
  lora: string;
  loraClass: string;
  sampler: string;
  positive: string | null;
  negative: string | null;
  latent: string | null;
  loader: Partial<Record<'model' | 'te' | 'vae', { node: string; input: string }>>;
  samplerTargets: { node: string; input: string; field: string }[];
  keep: string[];
}

function graph(api: ApiPrompt) {
  const consumers: Record<string, string[]> = {};
  for (const [id, n] of Object.entries(api))
    for (const v of Object.values(n.inputs)) if (isLink(v)) (consumers[v[0]] ??= []).push(id);
  const walk = (start: string[], next: (id: string) => string[]) => {
    const seen = new Set<string>();
    const order: string[] = [];
    const q = [...start];
    while (q.length) {
      const id = q.shift()!;
      if (seen.has(id) || !api[id]) continue;
      seen.add(id);
      order.push(id);
      q.push(...next(id));
    }
    return order;
  };
  const inputsOf = (id: string) => Object.values(api[id]?.inputs ?? {}).filter(isLink).map(v => v[0]);
  return {
    descendants: (id: string) => walk([id], x => consumers[x] ?? []).slice(1),
    ancestors: (ids: string[]) => walk(ids, inputsOf),
    upstreamFrom: (link: any) => (isLink(link) ? walk([link[0]], inputsOf) : []),
  };
}

const titleOf = (api: ApiPrompt, id: string) => api[id]?._meta?.title || api[id]?.class_type || id;

export async function analyzeWorkflow(source: ApiPrompt): Promise<WorkflowMap> {
  // the Pool/Cycler feeding a LoRA Manager loader is unplugged per image, so ignore it here
  const api: ApiPrompt = JSON.parse(JSON.stringify(source));
  const loras = Object.keys(api)
    .filter(id => LORA_CLASSES.includes(api[id].class_type))
    .sort((a, b) => {
      const aitk = (id: string) => (/aitk/i.test(titleOf(api, id)) ? 0 : 1);
      return aitk(a) - aitk(b) || parseFloat(a) - parseFloat(b) || a.localeCompare(b);
    });
  if (!loras.length) {
    throw new Error(`No LoRA loader in the workflow (needs one of: ${LORA_CLASSES.join(', ')}).`);
  }
  for (const id of loras) delete api[id].inputs.lora_stack;

  const outputNode: Record<string, boolean> = {};
  for (const cls of Array.from(new Set(Object.values(api).map(n => n.class_type)))) {
    outputNode[cls] = !!(await objectInfo(cls))?.output_node;
  }

  const g = graph(api);
  for (const lora of loras) {
    const desc = g.descendants(lora);
    const outputs = desc.filter(id => outputNode[api[id].class_type]);
    const sampler = desc.find(id => SAMPLER_RE.test(api[id].class_type));
    if (!outputs.length || !sampler) continue;
    // keep only what this lane's outputs need; other lanes and the Pool/Cycler drop out
    const keep = g.ancestors(outputs);
    const keepSet = new Set(keep);

    const s = api[sampler].inputs;
    let posLink = s.positive;
    let negLink = s.negative;
    if (!posLink && isLink(s.guider)) {
      const guider = api[s.guider[0]].inputs;
      posLink = guider.positive ?? guider.conditioning;
      negLink = guider.negative;
    }
    const textNode = (link: any) => g.upstreamFrom(link).find(id => 'text' in api[id].inputs) ?? null;
    const positive = textNode(posLink);
    const negative = negLink ? textNode(negLink) : null;

    const latentLink = s.latent_image ?? s.latent;
    const hasSize = (id: string) => 'width' in api[id].inputs && 'height' in api[id].inputs;
    const latent =
      g.upstreamFrom(latentLink).find(id => /latent/i.test(api[id].class_type) && hasSize(id)) ??
      keep.find(id => /empty.*latent/i.test(api[id].class_type) && hasSize(id)) ??
      null;

    const loader: WorkflowMap['loader'] = {};
    for (const [field, names] of Object.entries(LOADER_FIELDS) as [keyof typeof LOADER_FIELDS, string[]][]) {
      for (const id of keep) {
        const input = names.find(n => n in api[id].inputs && !isLink(api[id].inputs[n]));
        if (input) {
          loader[field] = { node: id, input };
          break;
        }
      }
    }

    const samplerTargets: WorkflowMap['samplerTargets'] = [];
    for (const id of [sampler, ...g.ancestors([sampler]).slice(1)]) {
      if (!keepSet.has(id) || !SAMPLER_CHAIN_RE.test(api[id].class_type)) continue;
      for (const [field, names] of Object.entries(SAMPLE_FIELDS)) {
        const input = names.find(n => n in api[id].inputs);
        if (input) samplerTargets.push({ node: id, input, field });
      }
    }

    return { lora, loraClass: api[lora].class_type, sampler, positive, negative, latent, loader, samplerTargets, keep };
  }
  throw new Error('Found a LoRA loader, but nothing it feeds reaches a sampler and an image output (Save/Preview).');
}

// What the workflow currently holds, so a new comparison can start from the user's own values.
// A linked widget (e.g. a shared "sampler control" node) is read from the node it comes from.
export async function workflowValues(api: ApiPrompt, map: WorkflowMap) {
  const read = async (node: string, input: string, depth = 0): Promise<any> => {
    const v = api[node]?.inputs?.[input];
    if (!isLink(v) || depth > 4) return v;
    const src = api[v[0]];
    if (!src) return undefined;
    if ('value' in src.inputs) return read(v[0], 'value', depth + 1);
    const names: string[] = (await objectInfo(src.class_type))?.output_name ?? [];
    const name = names[v[1]];
    return name && name in src.inputs ? read(v[0], name, depth + 1) : undefined;
  };
  const out: Record<string, any> = {};
  for (const t of map.samplerTargets) if (out[t.field] === undefined) out[t.field] = await read(t.node, t.input);
  if (map.positive) out.prompt = await read(map.positive, 'text');
  if (map.negative && map.negative !== map.positive) out.neg = await read(map.negative, 'text');
  if (map.latent) {
    out.width = await read(map.latent, 'width');
    out.height = await read(map.latent, 'height');
  }
  for (const [field, t] of Object.entries(map.loader)) if (t) out[field] = api[t.node].inputs[t.input];
  return out;
}

// dropdown choices for the panel, straight from Comfy so they match what it can load
export async function workflowOptions(api: ApiPrompt, map: WorkflowMap) {
  const combo = async (cls: string, input: string): Promise<string[]> => {
    const info = await objectInfo(cls);
    const spec = info?.input?.required?.[input] ?? info?.input?.optional?.[input];
    if (!spec) return [];
    if (Array.isArray(spec[0])) return spec[0];
    return Array.isArray(spec[1]?.options) ? spec[1].options : [];
  };
  const opts: Record<string, string[]> = {};
  for (const [field, t] of Object.entries(map.loader)) if (t) opts[field] = await combo(api[t.node].class_type, t.input);
  opts.sampler = await combo('KSampler', 'sampler_name');
  opts.scheduler = await combo('KSampler', 'scheduler');
  return opts;
}

export function describeMap(api: ApiPrompt, map: WorkflowMap) {
  const t = (id: string | null | undefined) => (id ? `${titleOf(api, id)} (#${id})` : null);
  return {
    lora: t(map.lora),
    sampler: t(map.sampler),
    positive: t(map.positive),
    negative: map.negative && map.negative !== map.positive ? t(map.negative) : null,
    latent: t(map.latent),
    loader: t(map.loader.model?.node ?? map.loader.te?.node ?? map.loader.vae?.node),
  };
}

// core LoRA loaders take a name from Comfy's own lora list; match the file by folder + file name
export async function comfyLoraName(loraClass: string, loraPath: string): Promise<string> {
  const info = await objectInfo(loraClass);
  const list: string[] = info?.input?.required?.lora_name?.[0] ?? [];
  const parts = loraPath.split(/[\\/]/);
  const tail2 = parts.slice(-2).join('/').toLowerCase();
  const norm = (s: string) => s.replace(/\\/g, '/').toLowerCase();
  const hit =
    list.find(n => norm(n).endsWith('/' + tail2) || norm(n) === tail2) ??
    list.find(n => norm(n).split('/').pop() === parts[parts.length - 1].toLowerCase());
  if (!hit) {
    throw new Error(`ComfyUI can't see ${loraPath}. Add its folder to ComfyUI's LoRA folders (extra_model_paths.yaml).`);
  }
  return hit;
}

export async function buildPrompt(
  source: ApiPrompt,
  map: WorkflowMap,
  cell: { loraPath: string; prompt: string },
  s: CompareSettings,
): Promise<ApiPrompt> {
  const keep = new Set(map.keep);
  const api: ApiPrompt = {};
  for (const id of map.keep) api[id] = JSON.parse(JSON.stringify(source[id]));

  const lora = api[map.lora].inputs;
  delete lora.lora_stack;
  if (map.loraClass === LM_LORA) {
    // LoRA Manager loads from its "loras" list; an absolute path that exists is always accepted,
    // so checkpoints a running training just saved work before the library rescans
    lora.loras = { __value__: [{ name: cell.loraPath, strength: s.strength, clipStrength: s.strength, active: true }] };
    lora.text = '';
  } else {
    lora.lora_name = await comfyLoraName(map.loraClass, cell.loraPath);
    lora.strength_model = s.strength;
    if ('strength_clip' in lora) lora.strength_clip = s.strength;
  }

  if (map.positive) api[map.positive].inputs.text = cell.prompt;
  if (map.negative && map.negative !== map.positive && keep.has(map.negative)) api[map.negative].inputs.text = s.neg ?? '';
  if (map.latent) {
    api[map.latent].inputs.width = s.width;
    api[map.latent].inputs.height = s.height;
    if ('batch_size' in api[map.latent].inputs) api[map.latent].inputs.batch_size = 1;
  }
  const values: Record<string, any> = { seed: s.seed, steps: s.steps, cfg: s.cfg, sampler: s.sampler, scheduler: s.scheduler };
  for (const t of map.samplerTargets) if (values[t.field] !== undefined && values[t.field] !== '') api[t.node].inputs[t.input] = values[t.field];
  for (const field of ['model', 'te', 'vae'] as const) {
    const t = map.loader[field];
    if (t && s[field]) api[t.node].inputs[t.input] = s[field];
  }
  return api;
}

// Comfy's validation errors come back as { error, node_errors: { id: { errors: [...] } } }
export function comfyErrorText(body: any): string {
  const parts: string[] = [];
  if (body?.error?.message) parts.push(body.error.message + (body.error.details ? `: ${body.error.details}` : ''));
  for (const [id, ne] of Object.entries<any>(body?.node_errors ?? {})) {
    for (const e of ne?.errors ?? []) parts.push(`#${id} ${ne.class_type ?? ''}: ${e.message}${e.details ? ` (${e.details})` : ''}`);
  }
  return parts.join(' · ') || JSON.stringify(body).slice(0, 400);
}
